@startuml
class Animal {
  +identifier : long
  +name : string
  +breed : string
}

class Owner {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Breed {
  +name : string
}

class Physician {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Appointment {
  +date : date
  +time : time
}

class MedicalCondition {
  +common_name : string
  +scientific_name : string
}

"1" -- "0..*" Animal : owns
"1" -- "*" Appointment : attends
"1" -- "1" Physician : responsible_for
"1" -- "*" Appointment : attends
"1" -- "*" Appointment : attends
"1" -- "*" Breed : has_common_conditions
"1" -- "*" MedicalCondition : is_common_to
"1" -- "*" MedicalCondition : is_detected_in
"0..1" -- "1" Animal : belongs_to
"1" -- "*" Animal : is_of_breed
@enduml

